originalPlan.program:
function meshLabel(id){
  if(id==="basePlate")return "底座基座";
  if(id==="turret")return "底座转台";
  if(id==="upperArm")return "第一节臂";
  if(id==="elbowJoint")return "肘部关节";
  if(id==="foreArm")return "第二节臂";
  if(id==="wrist")return "手腕";
  if(id==="gripper")return "末端夹爪";
  if(id==="floor")return "工作面";
  return "";
}
function partInfo(id){
  if(id==="basePlate")return "底座基座：固定在地面上不动，底座转台在它上面左右转。";
  if(id==="turret")return "底座转台：绕竖直轴左右转，整条手臂跟着它一起转。";
  if(id==="upperArm")return "第一节臂：随底座转台左右转，本身没有独立关节。";
  if(id==="elbowJoint")return "肘部关节：绕水平轴上下折，弯曲点就在两节臂之间。";
  if(id==="foreArm")return "第二节臂：跟着肘部关节上下折，末端会因此抬高或降低。";
  if(id==="wrist")return "手腕：第二节臂末端的连接件，随第二节臂一起运动。";
  if(id==="gripper")return "末端夹爪：装在手腕上，跟着第二节臂一起运动。";
  if(id==="floor")return "工作面：点击地面空白处会取消选中。";
  return "点击场景里的任意部件，就能看到它属于哪一节。";
}
function init(inputs,ctx){return {selected:""};}
function reduce(state,event,ctx){
  if(event.type==="scene-pick"){
    const id=event.object;
    if(id&&id!=="floor")state.selected=id;else state.selected="";
  }
  return state;
}
function advance(state,dt,ctx){return state;}
function project(state,inputs,ctx){
  const yaw=inputs.baseYaw*Math.PI/180;
  const elbow=inputs.elbowAngle*Math.PI/180;
  const sel=state.selected||"";
  const HL="#f2b134";
  const jointY=0.88;
  const tipY=jointY+1.65*Math.sin(elbow);
  const pose="底座 "+inputs.baseYaw+"° · 肘部 "+inputs.elbowAngle+"°";
  const tip="末端离地约 "+tipY.toFixed(2)+" 米";
  const selection=sel?("选中："+meshLabel(sel)):"未选中任何部件";
  const info=partInfo(sel);
  const summary=pose+"；"+selection;
  const groups=[
    {id:"pedestal",position:[0,0,0],rotation:[0,0,0],scale:[1,1,1]},
    {id:"root",position:[0,0,0],rotation:[0,yaw,0],scale:[1,1,1]},
    {id:"elbow",parent:"root",position:[1.6,jointY,0],rotation:[0,0,elbow],scale:[1,1,1]}
  ];
  const meshes=[
    {id:"floor",label:"工作面",geometry:{kind:"plane",width:9,height:9},position:[0,-0.01,0],rotation:[-1.5707963267948966,0,0],scale:[1,1,1],color:sel==="floor"?HL:"#4b5462"},
    {id:"basePlate",label:"底座基座",parent:"pedestal",geometry:{kind:"cylinder",radiusTop:0.78,radiusBottom:0.9,height:0.2,segments:24},position:[0,0.1,0],rotation:[0,0,0],scale:[1,1,1],color:sel==="basePlate"?HL:"#5b6472"},
    {id:"turret",label:"底座转台",parent:"root",geometry:{kind:"cylinder",radiusTop:0.5,radiusBottom:0.5,height:0.55,segments:24},position:[0,0.475,0],rotation:[0,0,0],scale:[1,1,1],color:sel==="turret"?HL:"#7b8698"},
    {id:"upperArm",label:"第一节臂",parent:"root",geometry:{kind:"box",size:[1.3,0.28,0.28]},position:[0.95,jointY,0],rotation:[0,0,0],scale:[1,1,1],color:sel==="upperArm"?HL:"#2f7fa8"},
    {id:"elbowJoint",label:"肘部关节",parent:"elbow",geometry:{kind:"cylinder",radiusTop:0.22,radiusBottom:0.22,height:0.46,segments:16},position:[0,0,0],rotation:[1.5707963267948966,0,0],scale:[1,1,1],color:sel==="elbowJoint"?HL:"#d0803a"},
    {id:"foreArm",label:"第二节臂",parent:"elbow",geometry:{kind:"box",size:[1.28,0.24,0.24]},position:[0.64,0,0],rotation:[0,0,0],scale:[1,1,1],color:sel==="foreArm"?HL:"#3f9c6d"},
    {id:"wrist",label:"手腕",parent:"elbow",geometry:{kind:"cylinder",radiusTop:0.13,radiusBottom:0.13,height:0.16,segments:16},position:[1.34,0,0],rotation:[0,0,1.5707963267948966],scale:[1,1,1],color:sel==="wrist"?HL:"#9aa3b2"},
    {id:"gripper",label:"末端夹爪",parent:"elbow",geometry:{kind:"box",size:[0.3,0.3,0.22]},position:[1.5,0,0],rotation:[0,0,0],scale:[1,1,1],color:sel==="gripper"?HL:"#c85a5a"}
  ];
  return {summary:summary,bindings:{pose:pose,tip:tip,selection:selection,partInfo:info},
    scenes:{arm:{camera:{position:[3.0,3.4,5.6],target:[0.9,0.9,0],fov:45},selected:sel||null,groups:groups,meshes:meshes}}};
}
